class MainActivity:ComponentActivity(){
 private val db by lazy{FactoryDatabase.get(this)}
 override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);lifecycleScope.launch{if(db.factoryDao().activeProducts().isEmpty()) listOf(ProductEntity(name="300ml",sizeLabel="300ml",bottlesPerPack=300),ProductEntity(name="500ml",sizeLabel="500ml",bottlesPerPack=200),ProductEntity(name="1 Ltr",sizeLabel="1 litre",bottlesPerPack=120),ProductEntity(name="200ml Green",sizeLabel="200ml",colour="Green",bottlesPerPack=300),ProductEntity(name="200ml Milk White",sizeLabel="200ml",colour="Milk White",bottlesPerPack=300),ProductEntity(name="200ml Clear",sizeLabel="200ml",bottlesPerPack=300)).forEach{runCatching{db.factoryDao().insertProduct(it)}}};if(FirebaseApp.getApps(this).isNotEmpty()) SyncScheduler.schedule(this);setContent{FactoryApp(db.factoryDao())}}
}
private enum class PageTab{HOME,PRODUCTS,PRODUCTION,PACKING,STOCK,DISPATCH,ELECTRICITY,REPORTS,CUSTOMERS}
@OptIn(ExperimentalMaterial3Api::class)
@Composable private fun FactoryApp(dao:FactoryDao){
 var tab by remember{mutableStateOf(PageTab.HOME)}; var dialog by remember{mutableStateOf("")}; var session by remember{mutableStateOf<FactorySession?>(null)}; var editingProduct by remember{mutableStateOf<ProductEntity?>(null)}; var reversalBatchId by remember{mutableStateOf<Long?>(null)}; var message by remember{mutableStateOf<String?>(null)}; var reportFrom by remember{mutableStateOf(today().substring(0,7)+"-01")}; var reportTo by remember{mutableStateOf(today())}; val scope=rememberCoroutineScope()
 val products by dao.observeProducts().collectAsStateWithLifecycle(emptyList()); val production by dao.observeProduction().collectAsStateWithLifecycle(emptyList()); val packing by dao.observePacking().collectAsStateWithLifecycle(emptyList()); val dispatches by dao.observeDispatches().collectAsStateWithLifecycle(emptyList()); val dispatchBatches by dao.observeDispatchBatches().collectAsStateWithLifecycle(emptyList()); val dispatchLines by dao.observeDispatchLines().collectAsStateWithLifecycle(emptyList()); val meters by dao.observeMeterReadings().collectAsStateWithLifecycle(emptyList()); val customers by dao.observeCustomers().collectAsStateWithLifecycle(emptyList()); val active=products.filter{it.active}; val date=today()
 val context=LocalContext.current
 LaunchedEffect(context){session=runCatching{FactoryAuthRepository(context).currentSession()}.getOrNull()}
 val exportLauncher=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("text/csv")) { uri ->
  if(uri!=null) runCatching { context.contentResolver.openOutputStream(uri)?.bufferedWriter()?.use { it.write(ReportExport.csv(production,packing,dispatches,meters,dispatchBatches,dispatchLines)) } ?: error("Could not open export destination") }.onSuccess { message="CSV report exported" }.onFailure { message="Export failed: "+it.message }
 }
 MaterialTheme(colorScheme=lightColorScheme(primary=Blue,secondary=Cyan,background=Page,surface=Color.White)){
 Scaffold(topBar={TopAppBar(title={Column{Text("TCK FactoryFlow",fontWeight=FontWeight.Bold,color=Navy);Text("Bottle Manufacturing Management",fontSize=11.sp,color=Blue)}},actions={TextButton(onClick={dialog="login"}){Text(session?.let{it.role.uppercase()}?:"SIGN IN",fontSize=10.sp,color=Blue)}},colors=TopAppBarDefaults.topAppBarColors(containerColor=Color.White))},bottomBar={NavigationBar(containerColor=Color.White){listOf(PageTab.HOME,PageTab.PRODUCTION,PageTab.STOCK,PageTab.REPORTS,PageTab.PRODUCTS).forEach{t->NavigationBarItem(selected=tab==t,onClick={tab=t},icon={Icon(when(t){PageTab.HOME->Icons.Default.Home;PageTab.PRODUCTION->Icons.Default.Build;PageTab.STOCK->Icons.Default.Inventory2;PageTab.REPORTS->Icons.Default.BarChart;else->Icons.Default.WaterDrop},null)},label={Text(t.name.lowercase().replaceFirstChar{it.uppercase()},fontSize=9.sp)})}}},containerColor=Page){padding->
 Box(Modifier.fillMaxSize().padding(padding)){
