 item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Metric("Packs completed",packing.filter{it.packingDate==date}.sumOf{it.completePacks}.toString(),Modifier.weight(1f));Metric("Packs dispatched",(dispatches.filter{it.dispatchDate==date}.sumOf{it.packsDispatched}+dispatchLines.filter{line->line.batchId in dispatchBatches.filter{it.status=="POSTED"&&it.dispatchDate==date}.map{it.id}}.sumOf{it.packs}).toString(),Modifier.weight(1f))}}
