 item{Text("Quick actions",fontSize=18.sp,fontWeight=FontWeight.Bold,color=Navy)}
 item{Column(verticalArrangement=Arrangement.spacedBy(8.dp)){Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Action("Production",Icons.Default.Build,{dialog="production"},Modifier.weight(1f));Action("Packing",Icons.Default.Inventory2,{dialog="packing"},Modifier.weight(1f));Action("Dispatch",Icons.Default.LocalShipping,{dialog="dispatch"},Modifier.weight(1f))};Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Action("Products",Icons.Default.WaterDrop,{tab=PageTab.PRODUCTS},Modifier.weight(1f));Action("Electricity",Icons.Default.Bolt,{dialog="meter"},Modifier.weight(1f));Action("Reports",Icons.Default.BarChart,{tab=PageTab.REPORTS},Modifier.weight(1f))};Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Action("Customers",Icons.Default.People,{tab=PageTab.CUSTOMERS},Modifier.weight(1f));Spacer(Modifier.weight(2f))}}}
 item{Text("Product pack settings",fontSize=18.sp,fontWeight=FontWeight.Bold,color=Navy)};items(active){p->Record(p.name,p.bottlesPerPack.toString()+" bottles per pack",p.colour)}
 item{Text("Recent production",fontSize=18.sp,fontWeight=FontWeight.Bold,color=Navy)};items(production.take(8)){e->Record(e.productNameSnapshot,e.goodBottles.toString()+" good · "+e.rejectedBottles+" rejected",e.productionDate)}
 }
 PageTab.PRODUCTS->Column(Modifier.fillMaxSize().padding(16.dp)){Row(verticalAlignment=Alignment.CenterVertically){Text("Product Master",Modifier.weight(1f),fontSize=23.sp,fontWeight=FontWeight.Bold,color=Navy);Button(onClick={editingProduct=null;dialog="product"}){Text("+ Add")}};LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){items(products){p->Record(p.name,p.sizeLabel+" · "+p.bottlesPerPack+" bottles/pack",if(p.active)"Active" else "Archived");if(p.active)Row{TextButton(onClick={editingProduct=p;dialog="product"}){Text("Edit")};TextButton(onClick={scope.launch{runCatching{dao.updateProductWithHistory(p.id,p.name,p.sizeLabel,p.colour,p.bottlesPerPack,false,session?.uid?:"local","Product deactivated",session?.organisationId?:"local-org")}.onSuccess{message="Product archived with history"}.onFailure{message=it.message}}}){Text("Deactivate")}}}}}
 PageTab.PRODUCTION->ListScreen("Production",production.map{Triple(it.productNameSnapshot,"Produced "+it.producedBottles+" · Good "+it.goodBottles+" · Reject "+it.rejectedBottles,it.productionDate)}, {dialog="production"})
 PageTab.PACKING->ListScreen("Packing / Finishing",packing.map{Triple(it.productNameSnapshot,it.completePacks.toString()+" packs · "+it.looseBottles+" loose bottles",it.packingDate)}, {dialog="packing"})
 PageTab.DISPATCH->Column(Modifier.fillMaxSize().padding(16.dp)){Row(verticalAlignment=Alignment.CenterVertically){Text("Delivery / Dispatch",Modifier.weight(1f),fontSize=21.sp,fontWeight=FontWeight.Bold,color=Navy);Button(onClick={dialog="dispatch"}){Text("+ Dispatch")}};LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){items(dispatchBatches){batch->Surface(color=Color.White,shape=RoundedCornerShape(12.dp)){Column(Modifier.fillMaxWidth().padding(12.dp)){Text(batch.customerNameSnapshot,fontWeight=FontWeight.Bold,color=Navy);Text(dispatchLines.filter{it.batchId==batch.id}.joinToString(" · "){it.productNameSnapshot+" × "+it.packs+" packs"},fontSize=12.sp,color=Blue);Text(batch.dispatchDate+" · "+batch.dispatchReference+" · "+batch.status,fontSize=10.sp,color=Color.Gray);if(batch.status=="POSTED"&&(session==null||session?.role in setOf("owner","admin","manager")))TextButton(onClick={reversalBatchId=batch.id;dialog="reverse"}){Text("Reverse dispatch")}}}};items(dispatches){e->Record(e.customerName,e.productNameSnapshot+" · "+e.packsDispatched+" packs",e.dispatchDate+" · "+e.dispatchReference)}}}
 PageTab.ELECTRICITY->ListScreen("Electricity",meters.map{Triple(it.meterId,it.consumption.toString()+" units",it.readingDate)}, {dialog="meter"})
 PageTab.CUSTOMERS->Column(Modifier.fillMaxSize().padding(16.dp)){Row(verticalAlignment=Alignment.CenterVertically){Text("Customers",Modifier.weight(1f),fontSize=23.sp,fontWeight=FontWeight.Bold,color=Navy);Button(onClick={dialog="customer"}){Text("+ Add")}};LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){items(customers){customer->Record(customer.name,customer.phone.ifBlank{"No phone"},customer.address.ifBlank{"No address"})}}}
 PageTab.STOCK->LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){item{Text("Finished Stock",fontSize=23.sp,fontWeight=FontWeight.Bold,color=Navy)};items(active){p->val packsMade=packing.filter{it.productId==p.id}.sumOf{it.completePacks};val legacySent=dispatches.filter{it.productId==p.id}.sumOf{it.packsDispatched};val batchSent=dispatchLines.filter{it.productId==p.id&&it.batchId in dispatchBatches.filter{b->b.status=="POSTED"}.map{b->b.id}}.sumOf{it.packs};val sent=legacySent+batchSent;Record(p.name,"Available packs: "+(packsMade-sent).coerceAtLeast(0),"Packed "+packsMade+" · Dispatched "+sent)}}
 PageTab.REPORTS->LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){
 item{Text("Reports & Analytics",fontSize=23.sp,fontWeight=FontWeight.Bold,color=Navy);Text("Saved records · daily / weekly / monthly / custom range",fontSize=12.sp,color=Blue);Button(onClick={exportLauncher.launch("factoryflow-report-"+date+".csv")},modifier=Modifier.fillMaxWidth()){Text("Export CSV / Backup")}}
 item{OutlinedTextField(reportFrom,{reportFrom=it},label={Text("From date (yyyy-MM-dd)")},singleLine=true,modifier=Modifier.fillMaxWidth());OutlinedTextField(reportTo,{reportTo=it},label={Text("To date (yyyy-MM-dd)")},singleLine=true,modifier=Modifier.fillMaxWidth())}
 item{val totals=runCatching{ReportExport.totals(java.time.LocalDate.parse(reportFrom),java.time.LocalDate.parse(reportTo),production,packing,dispatches,meters,dispatchBatches,dispatchLines)}.getOrNull();if(totals==null)Text("Enter valid dates in yyyy-MM-dd format; end date must not precede start date.",color=Color.Red) else Column(verticalArrangement=Arrangement.spacedBy(8.dp)){Text("Selected period",fontWeight=FontWeight.Bold,color=Navy);Metric("Produced bottles",totals.produced.toString(),Modifier.fillMaxWidth());Metric("Good / rejected",totals.good.toString()+" / "+totals.rejected,Modifier.fillMaxWidth());Metric("Packed bottles",totals.packedBottles.toString(),Modifier.fillMaxWidth());Metric("Complete packs",totals.completePacks.toString(),Modifier.fillMaxWidth());Metric("Dispatched packs",totals.dispatchedPacks.toString(),Modifier.fillMaxWidth());Metric("Electricity",totals.electricity.toString()+" units",Modifier.fillMaxWidth())}}
 item{val comparison=runCatching{val from=java.time.LocalDate.parse(reportFrom);val to=java.time.LocalDate.parse(reportTo);val days=java.time.temporal.ChronoUnit.DAYS.between(from,to)+1;val priorTo=from.minusDays(1);val priorFrom=priorTo.minusDays(days-1);ReportExport.totals(priorFrom,priorTo,production,packing,dispatches,meters,dispatchBatches,dispatchLines)}.getOrNull();if(comparison!=null){Text("Previous equal-length period",fontWeight=FontWeight.Bold,color=Navy);Text("Produced: "+comparison.produced+" · Packed: "+comparison.completePacks+" packs · Dispatched: "+comparison.dispatchedPacks+" packs · Electricity: "+comparison.electricity+" units",fontSize=12.sp,color=Blue)}}
}
 }
 message?.let{Text(it,Modifier.align(Alignment.BottomCenter).padding(12.dp).background(Color.White,RoundedCornerShape(12.dp)).padding(12.dp),color=Blue)}
 }
 }
 }
 if(dialog=="reverse"&&reversalBatchId!=null)ReverseDispatchForm({dialog="";reversalBatchId=null}){reason->scope.launch{runCatching{dao.reverseDispatch(reversalBatchId!!,reason,session?.uid?:"local",session?.organisationId?:"local-org");"Dispatch reversed"}.onSuccess{message=it}.onFailure{message=it.message}};dialog="";reversalBatchId=null}
 if(dialog=="login")LoginForm({dialog=""}){email,password->scope.launch{runCatching{FactoryAuthRepository(context).signIn(email,password)}.onSuccess{session=it;message="Signed in as "+it.role+" · "+it.organisationId}.onFailure{message=it.message}};dialog=""}
